1308:   findLanding() {
1309:     const rp = this.world.raftPos;
1310:     let best = null;
1311:     for (const island of this.world.islands) {
1312:       const dx = rp.x - island.x;
1313:       const dz = rp.z - island.z;
1314:       const dist = Math.hypot(dx, dz);
1315:       if (dist > island.radius * 1.34 || dist < 0.01) continue;
1316:       const dirx = dx / dist, dirz = dz / dist;
1317:       for (let t = 1.1; t >= 0.7; t -= 0.018) {
1318:         const x = island.x + dirx * island.radius * t;
1319:         const z = island.z + dirz * island.radius * t;
1320:         const h = this.world.heightAt(x, z);
1321:         if (h > 0.42) {
1322:           const d = Math.hypot(x - rp.x, z - rp.z);
1323:           if (d < 10.5 && (!best || d < best.d)) {
1324:             best = { pos: new THREE.Vector3(x, h + 0.05, z), island, d };
1325:           }
1326:           break;
1327:         }
1328:       }
1329:     }
1330:     return best;
1331:   }
