1337:     const ox = p.onRaft ? this.world.raftPos.x : p.pos.x;
1338:     const oz = p.onRaft ? this.world.raftPos.z : p.pos.z;
1339:     for (let d = 4.5; d <= 16; d += 1.1) {
1340:       const x = ox + fx * d;
1341:       const z = oz + fz * d;
1342:       if (this.world.heightAt(x, z) < -0.55) return { x, z };
1343:     }
1344:     return null;
1345:   }
