779:   makeRaftMesh(ghost = false) {
780:     const group = new THREE.Group();
781:     const logMat = new THREE.MeshStandardMaterial({
782:       color: ghost ? 0xb08a58 : 0x7a5330, roughness: 1,
783:       transparent: ghost, opacity: ghost ? 0.5 : 1,
784:     });
785:     const ropeMat = new THREE.MeshStandardMaterial({
786:       color: ghost ? 0xd8c39b : 0xb79a63, roughness: 1,
787:       transparent: ghost, opacity: ghost ? 0.6 : 1,
788:     });
789:     const logGeo = new THREE.CylinderGeometry(0.23, 0.23, 4.4, 7);
790:     logGeo.rotateX(Math.PI / 2);
791:     for (let i = 0; i < 7; i++) {
792:       const log = new THREE.Mesh(logGeo, logMat);
793:       log.position.set((i - 3) * 0.48, 0.2, 0);
794:       log.castShadow = !ghost;
795:       group.add(log);
796:     }
797:     for (const z of [-1.45, 0, 1.45]) {
798:       const beam = new THREE.Mesh(new THREE.BoxGeometry(3.35, 0.15, 0.28), ropeMat);
799:       beam.position.set(0, 0.47, z);
800:       group.add(beam);
801:     }
802:     // mast
803:     const mast = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.14, 4.4, 7), logMat);
804:     mast.position.set(0, 2.4, -0.4);
805:     mast.castShadow = !ghost;
806:     group.add(mast);
807:     const boom = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, 2.6, 6), logMat);
808:     boom.position.set(0, 3.1, -0.4);
809:     boom.rotation.z = Math.PI / 2;
810:     group.add(boom);
811:     // sail
812:     const sailCanvas = document.createElement('canvas');
813:     sailCanvas.width = 256; sailCanvas.height = 256;
814:     const ctx = sailCanvas.getContext('2d');
815:     ctx.fillStyle = '#f0e2c2';
816:     ctx.fillRect(0, 0, 256, 256);
817:     ctx.fillStyle = '#d8c49a';
818:     for (let i = 0; i < 4; i++) ctx.fillRect(0, i * 64 + 46, 256, 8);
819:     ctx.fillStyle = '#b45a3c';
820:     ctx.beginPath();
821:     ctx.arc(128, 120, 42, 0, Math.PI * 2);
822:     ctx.fill();
823:     ctx.fillStyle = '#f0e2c2';
824:     ctx.beginPath();
825:     ctx.arc(128, 120, 28, 0, Math.PI * 2);
826:     ctx.fill();
827:     const sailTex = new THREE.CanvasTexture(sailCanvas);
828:     sailTex.colorSpace = THREE.SRGBColorSpace;
829:     const sailMat = new THREE.MeshStandardMaterial({
830:       map: sailTex, side: THREE.DoubleSide, roughness: 1,
831:       transparent: ghost, opacity: ghost ? 0.45 : 1,
832:     });
833:     const sail = new THREE.Mesh(new THREE.PlaneGeometry(2.5, 2.3, 6, 6), sailMat);
834:     sail.position.set(0.02, 3.15, -0.4);
835:     sail.rotation.y = Math.PI / 2;
836:     sail.castShadow = !ghost;
837:     group.add(sail);
838:     // flag
839:     const flag = new THREE.Mesh(
840:       new THREE.PlaneGeometry(0.85, 0.45),
841:       new THREE.MeshStandardMaterial({ color: 0xd4553a, side: THREE.DoubleSide, roughness: 1 }),
842:     );
843:     flag.position.set(0.45, 4.35, -0.4);
844:     flag.rotation.y = Math.PI / 2;
845:     group.add(flag);
846:     // foam ring
847:     const foam = new THREE.Mesh(
848:       new THREE.RingGeometry(1.0, 1.55, 24),
849:       new THREE.MeshBasicMaterial({
850:         color: 0xd9fbff, transparent: true, opacity: ghost ? 0.02 : 0.28,
851:         depthWrite: false, blending: THREE.AdditiveBlending, side: THREE.DoubleSide,
852:       }),
853:     );
854:     foam.rotation.x = -Math.PI / 2;
855:     foam.position.y = 0.05;
856:     group.add(foam);
857:     group.userData.foam = foam;
858:     group.userData.sail = sail;
859:     return group;
860:   }
