908:   buildProps() {
909:     const allTrees = [];
910:     const allRocks = [];
911:     const allBushes = [];
912:     const allBranches = [];
913:     const treeRand = mulberry32(7741);
914:     const rockRand = mulberry32(9917);
915:     const bushRand = mulberry32(4241);
916:     const branchRand = mulberry32(3313);
917: 
918:     for (const island of this.islands) {
919:       const isHome = island.id === 'home';
920:       const treeCount = isHome ? 17 : 13;
921:       const rockCount = isHome ? 8 : 9;
922:       const bushCount = isHome ? 9 : 8;
923:       const vineCount = isHome ? 6 : 4;
924:       const branchCount = isHome ? 12 : 6;
925: 
926:       const blocked = (x, z, extra = 0) => {
927:         if (Math.hypot(x - island.shelterPos.x, z - island.shelterPos.z) < 8.5 + extra) return true;
928:         if (island.spawnPos && Math.hypot(x - island.spawnPos.x, z - island.spawnPos.z) < 7 + extra) return true;
929:         if (island.raftSitePos && Math.hypot(x - island.raftSitePos.x, z - island.raftSitePos.z) < 9 + extra) return true;
930:         return false;
931:       };
932: 
933:       for (let i = 0; i < treeCount; i++) {
934:         let x, z, h, tries = 0;
935:         do {
936:           const a = treeRand() * Math.PI * 2;
937:           const r = (0.24 + treeRand() * 0.6) * island.radius;
938:           x = island.x + Math.cos(a) * r;
939:           z = island.z + Math.sin(a) * r;
940:           h = this.heightAt(x, z);
941:           tries++;
942:         } while ((h < 1.0 || blocked(x, z, -2)) && tries < 40);
943:         if (h < 0.9) continue;
944:         const scale = 0.8 + treeRand() * 0.55;
945:         const rec = {
946:           type: 'tree', id: `tree-${island.id}-${i}`, islandId: island.id,
947:           pos: new THREE.Vector3(x, h, z), radius: 2.6,
948:           scale, trunkIdx: allTrees.length, hp: 3, maxHp: 3, alive: true,
949:           rot: treeRand() * Math.PI * 2,
950:           coconuts: 1 + (treeRand() > 0.45 ? 1 : 0),
951:         };
952:         allTrees.push(rec);
953:         const col = { x, z, r: 0.42 * scale, rec };
954:         this.colliders.push(col);
955:         rec.collider = col;
956:         this.interactables.push(rec);
957:       }
958: 
959:       for (let i = 0; i < rockCount; i++) {
960:         let x, z, h, tries = 0;
961:         do {
962:           const a = rockRand() * Math.PI * 2;
963:           const r = (0.28 + rockRand() * 0.52) * island.radius;
964:           x = island.x + Math.cos(a) * r;
965:           z = island.z + Math.sin(a) * r;
966:           h = this.heightAt(x, z);
967:           tries++;
968:         } while ((h < 0.5 || blocked(x, z)) && tries < 40);
969:         if (h < 0.3) continue;
970:         const sx = 0.7 + rockRand() * 1.35;
971:         const sy = 0.5 + rockRand() * 0.9;
972:         const sz = 0.7 + rockRand() * 1.2;
973:         const rec = {
974:           type: 'rock', id: `rock-${island.id}-${i}`, islandId: island.id,
975:           pos: new THREE.Vector3(x, h, z), radius: 2.2,
976:           rockIdx: allRocks.length, hp: 3.2, maxHp: 3.2, alive: true,
977:           scale: new THREE.Vector3(sx, sy, sz), rot: new THREE.Euler(rockRand() * 0.3, rockRand() * Math.PI * 2, rockRand() * 0.3),
978:         };
979:         allRocks.push(rec);
980:         const col = { x, z, r: Math.max(sx, sz) * 0.65, rec };
981:         this.colliders.push(col);
982:         rec.collider = col;
983:         this.interactables.push(rec);
984:       }
985: 
986:       for (let i = 0; i < bushCount; i++) {
987:         let x, z, h, tries = 0;
988:         do {
989:           const a = bushRand() * Math.PI * 2;
990:           const r = (0.3 + bushRand() * 0.55) * island.radius;
991:           x = island.x + Math.cos(a) * r;
992:           z = island.z + Math.sin(a) * r;
993:           h = this.heightAt(x, z);
994:           tries++;
995:         } while ((h < 0.8 || blocked(x, z, -3)) && tries < 40);
996:         if (h < 0.7) continue;
997:         const s = 0.7 + bushRand() * 0.6;
998:         const rec = {
999:           type: 'bush', id: `bush-${island.id}-${i}`, islandId: island.id,
1000:           pos: new THREE.Vector3(x, h, z), radius: 2.0,
1001:           bushIdx: allBushes.length, cooldown: 0, maxCooldown: 42, scale: s,
1002:           rot: bushRand() * Math.PI * 2,
1003:         };
1004:         allBushes.push(rec);
1005:         this.interactables.push(rec);
1006:       }
1007: 
1008:       // vine patches (rope source) - small individual groups
1009:       for (let i = 0; i < vineCount; i++) {
1010:         let x, z, h, tries = 0;
1011:         do {
1012:           const a = bushRand() * Math.PI * 2;
1013:           const r = (0.36 + bushRand() * 0.46) * island.radius;
1014:           x = island.x + Math.cos(a) * r;
1015:           z = island.z + Math.sin(a) * r;
1016:           h = this.heightAt(x, z);
1017:           tries++;
1018:         } while ((h < 1.0 || blocked(x, z, -2)) && tries < 40);
1019:         if (h < 0.9) continue;
1020:         const group = new THREE.Group();
1021:         group.position.set(x, h, z);
1022:         const leafMat = new THREE.MeshStandardMaterial({ color: 0x3f7d4b, roughness: 1, flatShading: true });
1023:         const stemMat = new THREE.MeshStandardMaterial({ color: 0x8a7a45, roughness: 1 });
1024:         for (let v = 0; v < 4; v++) {
1025:           const a = (v / 4) * Math.PI * 2 + Math.random() * 0.5;
1026:           const leaf = new THREE.Mesh(new THREE.ConeGeometry(0.42, 1.9, 5), leafMat);
1027:           leaf.position.set(Math.cos(a) * 0.3, 0.9, Math.sin(a) * 0.3);
1028:           leaf.rotation.z = Math.cos(a) * 0.45;
1029:           leaf.rotation.x = Math.sin(a) * 0.45;
1030:           leaf.castShadow = true;
1031:           group.add(leaf);
1032:           const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.045, 1.5, 5), stemMat);
1033:           stem.position.set(Math.cos(a) * 0.15, 0.75, Math.sin(a) * 0.15);
1034:           group.add(stem);
1035:         }
1036:         this.scene.add(group);
1037:         const rec = {
1038:           type: 'vine', id: `vine-${island.id}-${i}`, islandId: island.id,
1039:           pos: new THREE.Vector3(x, h + 0.8, z), radius: 2.2,
1040:           cooldown: 0, maxCooldown: 46, group,
1041:         };
1042:         this.interactables.push(rec);
1043:       }
1044: 
1045:       // loose branches on the beach
1046:       for (let i = 0; i < branchCount; i++) {
1047:         let x, z, h, tries = 0;
1048:         do {
1049:           const a = branchRand() * Math.PI * 2;
1050:           const r = (0.58 + branchRand() * 0.28) * island.radius;
1051:           x = island.x + Math.cos(a) * r;
1052:           z = island.z + Math.sin(a) * r;
1053:           h = this.heightAt(x, z);
1054:           tries++;
1055:         } while ((h < 0.25 || h > 2.6 || blocked(x, z, -4)) && tries < 40);
1056:         if (h < 0.2) continue;
1057:         const rec = {
1058:           type: 'branch', id: `branch-${island.id}-${i}`, islandId: island.id,
1059:           pos: new THREE.Vector3(x, h, z), radius: 1.7,
1060:           branchIdx: allBranches.length, alive: true,
1061:           rot: new THREE.Euler(0, branchRand() * Math.PI * 2, branchRand() * 0.2),
1062:         };
1063:         allBranches.push(rec);
1064:         this.interactables.push(rec);
1065:       }
1066:     }
1067: 
1068:     // ---- instanced trees ----
1069:     const trunkGeo = new THREE.CylinderGeometry(0.2, 0.42, 4.9, 6);
1070:     trunkGeo.translate(0, 2.45, 0);
1071:     const trunkMat = new THREE.MeshStandardMaterial({ color: 0x7f5a35, roughness: 1, flatShading: true });
1072:     const trunkMesh = new THREE.InstancedMesh(trunkGeo, trunkMat, allTrees.length);
1073:     trunkMesh.castShadow = !this.lowQuality;
