```js
function makeTuftGeometry() {
  const positions = [];
  const indices = [];
  let vi = 0;
  for (let b = 0; b < 3; b++) {
    const yaw = (b / 3) * Math.PI + 0.15 * b; // crossing
    const dx = Math.cos(yaw), dz = Math.sin(yaw);
    const w = 0.055, hgt = 0.62, bend = 0.14;
    // base left/right
    positions.push(-dx*w, 0, -dz*w, dx*w, 0, dz*w);
    positions.push(-dx*w*0.35 + dz*bend, hgt, -dz*w*0.35 - dx*bend);
    positions.push(dx*w*0.35 + dz*bend, hgt, dz*w*0.35 - dx*bend);
    indices.push(vi, vi+1, vi+3, vi, vi+3, vi+2);
    vi += 4;
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  g.setIndex(indices);
  g.computeVertexNormals();
  return g;
}
```

