playwright-cli eval "() => {
  const g=window.__islandGame;
  const out={};
  const teleport=(x,z)=>{const y=g.world.heightAt(x,z);g.player.pos.set(x,Math.max(y,0.1),z);};
  const useNear=(rec)=>{teleport(rec.pos.x,rec.pos.z+1);g.currentAction={type:'use',rec,short:'USAR'};g.interact();};
  // branch
  const branch=g.world.interactables.find(r=>r.type==='branch'&&r.alive);
  out.woodBefore=g.inventory.wood; useNear(branch); out.woodAfter=g.inventory.wood;
  // vine
  const vine=g.world.interactables.find(r=>r.type==='vine');
  out.ropeBefore=g.inventory.rope; useNear(vine); out.ropeAfter=g.inventory.rope;
  // craft
  g.inventory.wood=30;g.inventory.stone=10;g.inventory.rope=12;g.inventory.cloth=4;
  g.craft('axe');g.craft('spear');g.craft('rod');g.craft('torch');
  out.tools={...g.tools};
  // raft site
  const site=g.world.interactables.find(r=>r.type==='raftsite');
  useNear(site); out.raftBuilt=g.world.raftBuilt; out.invAfterRaft={wood:g.inventory.wood,rope:g.inventory.rope,cloth:g.inventory.cloth};
  // board and sail
  g.boardRaft(); out.onRaft=g.player.onRaft;
  const start={x:g.world.raftPos.x,z:g.world.raftPos.z};
  g.keys.add('KeyW');
  for(let i=0;i<60;i++) g.updateRaft(1/60);
  g.keys.delete('KeyW');
  out.sailed=Math.hypot(g.world.raftPos.x-start.x,g.world.raftPos.z-start.z);
  // chests: teleport to each chest and open directly
  g.player.onRaft=false;
  const chests=g.world.interactables.filter(r=>r.type==='chest'&&r.islandId!=='home');
  for(const c of chests){ useNear(c); }
  out.flares=g.inventory.flare; out.opened=chests.map(c=>c.opened);
  // fishing
  g.tools.rod=true;
  // find shore point: sample home shore angle
  const home=g.world.islands[0];
  const a=0.2; const x=home.x+Math.cos(a)*home.radius*0.99, z=home.z+Math.sin(a)*home.radius*0.99;
  teleport(x,z); g.player.yaw=Math.atan2(-Math.cos(a),-Math.sin(a)); g.player.pitch=-0.15;
  g.fishing.state='idle'; g.startFishing();
  out.fishState=g.fishing.state;
  if(g.fishing.state==='cast'){ g.fishing.timer=g.fishing.duration; g.updateFishing(0.016); out.biteState=g.fishing.state; g.catchFish(); }
  out.rawFish=g.inventory.rawFish; out.statsFish=g.stats.fish;
  return out;
